.Use_AD_and_BC { display:none; }
.Use_BCE_and_CE {display:inline; }
*/

/* Class for links with loudspeaker icon next to them */

.audiolink a{
	background: url("//thumb.wikimedia.org/wikipedia/commons/thumb/8/8a/Loudspeaker.svg/11px-Loudspeaker.svg.png") center left no-repeat !important;
	padding-left: 16px !important;
	padding-right: 0 !important;
}

/* Icons for medialist templates [[Template:Listen]], [[Template:Multi-listen_start]], [[Template:Video]], [[Template:Multi-video_start]] */

div.listenlist {
	background: url("//thumb.wikimedia.org/wikipedia/commons/thumb/a/a6/Gnome-speakernotes.png/30px-Gnome-speakernotes.png");
	padding-left: 40px;
}

div.videolist, div.multivideolist {
	background: url("//thumb.wikimedia.org/wikipedia/en/thumb/2/20/Tango-video-x-generic.png/40px-Tango-video-x-generic.png");
	padding-left: 50px;
}

/* Style rules for media list templates */

div.medialist {
	min-height: 50px;
	margin: 1em;
	background-position: top left;
	background-repeat: no-repeat;
}

div.medialist ul {
	list-style-type: none;
	list-style-image: none;
	margin: 0;
}

div.medialist ul li {
	padding-bottom: 0.5em;
}

div.medialist ul li li {
	font-size: 91%;
