/* Any JavaScript here will be loaded for all Internet Explorer users on every page load. */

/**
 * Helper script for .hlist class in Common.css
 * @source mediawiki.org/wiki/Snippets/Horizontal_lists
 * @revision 5 (2013-12-22)
 * @author [[User:Edokter]]
 */
( function ( mw, $ ) {
	var profile = $.client.profile();
	if ( profile.versionNumber === 8 ) {
		/* IE 8: Add pseudo-selector class to last-child list items */
		mw.hook( 'wikipage.content' ).add( function ( $content ) {
			$content.find( '.hlist' ).find( 'dd:last-child, dt:last-child, li:last-child' )
				.addClass( 'hlist-last-child' );
		} );
	}
	else if ( profile.versionNumber <= 7 ) {
		/* IE 7 and below: Generate interpuncts and parentheses */
		mw.hook( 'wikipage.content' ).add( function ( $content ) {
			var $hlists = $content.find( '.hlist' );
			$hlists.find( 'dt:not(:last-child)' )
				.append( ': ' );
			$hlists.find( 'dd:not(:last-child)' )
				.append( '<b>·</b> ' );
			$hlists.find( 'li:not(:last-child)' )
				.append( '<b>·</b> ' );
			$hlists.find( 'dl dl, dl ol, dl ul, ol dl, ol ol, ol ul, ul dl, ul ol, ul ul' )
				.prepend( '( ' ).append( ') ' );
		} );
	}
}( mediaWiki, jQuery ) );

=== Pronunciation === * {{IPA|/ˌmæntʃɪˈniːl/}}
== Noun == {{noun}} [[File:Hippomane mancinella (fruit).jpg|thumb|The fruit of a '''manchineel''' tree]] # A '''manchineel''' [[tree]] is a small American [[tropical]] tree that is extremely [[poisonous]].
[[Category:Trees]]

=== Word parts ===
{{ety-suffix|win|er}}

=== Pronunciation ===
* {{UK}} {{IPA|/ˈwɪnə/}}
* {{US}} {{IPA|/ˈwɪnɚ/}}
* {{audio|LL-Q1860 (eng)-Vealhurl-winner.wav|UK}}

== Noun ==
{{noun}}
# {{countable}} A '''winner''' is someone that has [[win|won]] a [[competition]], or often wins. {{ant|loser}} {{syn|victor}}
#: ''Terry is considered the '''winner''' since he came in first in the 100 meters race event.''

[[Category:People]]

=== Pronunciation ===
* {{IPA|/ˈflaɪə(r)/}}
* {{audio|LL-Q1860 (eng)-Vealhurl-flyer.wav|Audio (UK)}}

== Noun ==
{{noun}}
# {{countable}} A '''flyer''' is a [[leaflet]] or a piece of [[paper]] that is given to people on the [[street]]s as a form of {{r|advertiz|ing}}.
#: ''As I waited for my exam results, I took up a temporary job of {{r|distribut|ing}} '''flyers'''.''
# {{countable}} A '''flyer''' is someone that [[pilots]] or {{r|fl|ies}} an [[airplane]]. {{syn|pilot}}
# {{countable}} A [[machine]] that flies.

[[Category:People]]

=== Pronunciation ===
* {{US}} {{IPA|/luzɚ/}}
* {{IPA|/luːzə(r)/}}
* {{audio|LL-Q1860 (eng)-Vealhurl-loser.wav|Audio (UK)}}

== Noun ==
{{noun}}
# {{countable}} A '''loser''' is someone that did not [[win]] a [[competition]]. In sports, a loser would be one that did not come in [[first]] place. {{ant|winner}}
# Someone that is very often [[fail]]ing or being [[unsuccessful]] in [[life]]. {{syn|failure}}
#: ''He is such a '''loser'''!''

