.formsGadget .ui-state-hover{
	background: transparent;
	border-color: #a1a1a1;
}

.formsGadget.ui-dialog .ui-icon-closethick{
	background: url(data:image/svg+xml;base64,) no-repeat 50% 50% !important;
}

.formsGadget .ui-widget-content{
	background: #EEE;
}

.formsGadget.ui-dialog .ui-widget-header{
	border: none;
	background: #EEE !important;
	padding-left: 11px !important;
	margin-top: 25px;
}

.formsGadget.ui-widget-content{
	background: #EEE;
	padding: 10px 18px;
	color: #444; 
	border-left: 1px solid #ddd; 
	border-top: 1px solid #ddd; 
	border-right: 1px solid #ddd; 
	border-bottom: 3px solid #D0D0D0; 
	border-radius: 1px;
}

.formsGadget .gadgetControls{
	text-align: right;
	margin: 10px 0px;
}
/*Check*/
.formsGadget .messageDescription{
	margin: 10px 0px;
}

.formsGadget textarea,.formsGadget input[type=textbox],.formsGadget input[type=number]{
	outline: 0px;
	padding: 14px 7px;
	resize: none;
	background-color: white;
	border: 1px solid #DDD;
	border-radius: 1px;
	margin-bottom: 1em;
}

.formsGadget textarea:focus, .formsGadget input[type=textbox]:focus{
	box-shadow: inset .45em 0 0 #5088f7;
}

div.grantsHide{
	display: none;
}

.formsGadget mw-ui-vform{
	width: 100%;
}

.formsGadget textarea::-webkit-input-placeholder{
	font-style: italic;
}

.formsGadget textarea::-moz-placeholder {  /* Firefox 19+ */
    font-style: italic;
}
.formsGadget textarea:-ms-input-placeholder {  
	font-style: italic;
}

.formsGadget input::-webkit-input-placeholder{
	font-style: italic;
}

.formsGadget input::-moz-placeholder {  /* Firefox 19+ */
    font-style: italic;
}
.formsGadget input:-ms-input-placeholder {  
	font-style: italic;
}

.formsGadget input.entryNotSatisfying:focus{
	box-shadow: inset .45em 0 0 #D11D13;
}

.formsGadget input.entrySatisfying:focus{
	box-shadow: inset .45em 0 0 #5088f7;
}

.formsGadget .title{
	font-weight: bold;
}

