	margin-right: 30px;
}

.formsGadget input[type=textbox],.formsGadget input[type=number]{
	padding: 7px;
}

.formsGadget input[type=number]{
	text-align: center;
}
.formsGadget .inputListItemDescription{
	/* width: 120px; */
	display: inline-block;
}

.formsGadget .ui-widget-content a{
	color: #0b0080;
}

.formsGadget .ui-widget-content a span{
	color: #444444;
}

.formsGadget .validationContainer.entrySatisfying:after{
	content: url(data:image/png;base64,);
	padding: 7px 8px 7px 8px;
	background-color: #347BFF;
	border: 1px solid #DDD;
	border-width: 1px 1px 1px 0px;
}
.formsGadget .validationContainer.entryNotSatisfying:after{
	content: url(data:image/png;base64,);
	padding: 7px 8px 7px 8px;
	background-color: #D11D13;
	border: 1px solid #DDD;
	border-width: 1px 1px 1px 0px;
}
.formsGadget .inputElementWrapper{
	position: relative;
}
.formsGadget .mandatoryContainer:before{
	position: absolute;
	left: -6px;
	content: "*";
	color: #D11D13;
}
.formsGadget img{
	height: 100px;
}
.formsGadget input[type=textbox]{
	margin: 0px 0px 10px 0px;
	width: 90%;
}

.formsGadget input[type=submit]{
	margin-right: .5em;
	float: right;
}
/* Dropdown styling */
.formsGadget .chzn-container-single .chzn-single{
	background-image: none;
	border-radius: 1px;
	box-shadow: none;
	border: 1px solid #ddd;
	padding: .25em;
	padding-left: 14px;
}
.formsGadget .chzn-container .chzn-results li {
	padding-left: 10px;
}
.formsGadget .chzn-container-active.chzn-with-drop .chzn-single{
	/*Get a better color*/
	background: #F6F3F3;
	border: 1px solid #aaa;
	padding: .25em;
	padding-left: 14px;
}
.formsGadget .chzn-container .chzn-results .highlighted{
	background-image: none;
	background-color: #347bff;
}
.formsGadget .chzn-container-single .chzn-single div b{
	background-position: 0px 5px;
}
.formsGadget .chzn-container-active.chzn-with-drop .chzn-single div b{
	background-position: -18px 5px;
}

/* Dialog Loading*/
.formsGadget .loading{
	background: url(data:image/gif;base64,);
	width: 128px;
	height: 15px;
	margin: auto;
}

