  function skipPunctuation(tokens, state, valid) {
    var punctuation = [",", ":", "]", "}"];
    var token = popToken(tokens, state);
    while (true) { // eslint-disable-line no-constant-condition
      if (valid && valid.indexOf(token.type) !== -1) {
