-- Valid URI schemes in external links, which therefore have to be escaped if used in entry names (e.g. [[sms:a]]). local uri_schemes = { "bitcoin:", "ftp://", "ftps://", "geo:", "git://", "gopher://", "http://", "https://", "irc:", "ircs:", "magnet:", "mailto:", "mms://", "news:", "nntp://", "redis://", "sftp://", "sip:", "sips:", "sms:", "ssh://", "svn://", "tel:", "telnet://", "urn:", "worldwind://", "xmpp:", } -- Convert into lookup table. local uri_lookup = {} for _, scheme in ipairs(uri_schemes) do uri_lookup[scheme] = encode(scheme, ":") end data.uri_schemes = uri_lookup
