-- Regional labels
local m_regional = require("Module:labels/data/regional")

for key, val in pairs(m_regional.labels) do
	labels[key] = val
end

for key, val in pairs(m_regional.aliases) do
	aliases[key] = val
end

for key, val in pairs(m_regional.deprecated) do
	deprecated[key] = val
end


-- Topical labels

local m_topical = require("Module:labels/data/topical")

for key, val in pairs(m_topical.labels) do
	labels[key] = val
end

for key, val in pairs(m_topical.aliases) do
	aliases[key] = val
end

for key, val in pairs(m_topical.deprecated) do
	deprecated[key] = val
end

--[[	Add subvariety labels and the corresponding aliases
		and deprecated labels if they have a language code
		in the "languages" field.								]]
local m_subvarieties = require("Module:labels/data/subvarieties")

for key, val in pairs(m_subvarieties.labels) do
	if labels[key] then
		replacements.labels[key] = labels[key]
	end

	if val.languages then
		labels[key] = val
	end
end

for key, val in pairs(m_subvarieties.aliases) do
	if aliases[key] then
		replacements.aliases[key] = aliases[key]
	end

	if labels[val] then
		aliases[key] = val
	end
end

for key, val in pairs(m_subvarieties.deprecated) do
	if deprecated[key] then
		replacements.deprecated[key] = deprecated[key]
	end

	if labels[key] then
		deprecated[key] = val
	end
end

return {
	["labels"] = labels,
	["aliases"] = aliases,
	["deprecated"] = deprecated,
	["replacements"] = replacements,
}

local data = {}
data.notneeded = { ["und"] = true, ["cmn"] = true, ["ja"] = true, ["zu"] = true, ["nan"] = true, ["yue"] = true, ["ko"] = true, }
data.neededhassubpage = { ["ga"] = true, ["gv"] = true, ["nv"] = true, ["roa-jer"] = true, ["fr"] = true, ["rm"] = true, ["prg"] = true, ["gd"] = true, ["twf"] = true, ["en"] = true, ["ro"] = true, ["egl"] = true, ["roa-tar"] = true, ["gl"] = true, ["ast"] = true, ["br"] = true, }
--[[ Script that should be applied to links in categories. ]] data.catfix_scripts = { ["ab"] = "Cyrl", ["ae"] = "Avst", ["ar"] = "Arab", ["ary"] = "Arab", ["be"] = "Cyrl", ["cu"] = "Cyrs", ["el"] = "Grek", ["grc"] = "Polyt", ["he"] = "Hebr", ["ka"] = "Geor", ["orv"] = "Cyrs", ["ru"] = "Cyrl", ["sa"] = "Deva", ["syl"] = "Sylo", ["xfa"] = "Ital", ["zle-ono"] = "Cyrs", ["zle-ort"] = "Cyrs", ["hi"] = "Deva", ["mr"] = "Deva", --[[ [""] = "", ]] }
local lower = require("Module:string utilities").lower
local interwikis = {} for _, interwiki in pairs(mw.site.interwikiMap()) do interwikis[lower(interwiki.prefix)] = true end data.interwikis = interwikis
local namespaces = {} for _, namespace in pairs(mw.site.namespaces) do namespaces[lower(namespace.name)] = true for _, alias in pairs(namespace.aliases) do namespaces[lower(alias)] = true end end data.namespaces = namespaces
return data

local export = {}
local lang_en = require("Module:languages").getByCode("en") local lang_mul = require("Module:languages").getByCode("mul")
function export.taxon(frame) local params = { [1] = {required = true, default = "{{{1}}}"}, [2] = {required = true, default = "{{{2}}}"}, [3] = {required = true, default = "{{{3}}}"}, [4] = {},
["i"] = {type = "boolean"}, ["nodot"] = {type = "boolean"}, }
local args = require("Module:parameters").process(frame:getParent().args, params)
local ret = {} local categories = {"mul:Taxonomic names (" .. args[1] .. ")"}
table.insert(ret, "A taxonomic ") table.insert(ret, require("Module:links").language_link{lang = lang_en, term = args[1]}) table.insert(ret, " within the ") table.insert(ret, require("Module:links").language_link{lang = lang_en, term = args[2]}) table.insert(ret, " ")
local parent = require("Module:links").language_link{lang = lang_mul, term = args[3]}
if args[2] == "genus" or args[2] == "species" or args["i"] then parent = "''" .. parent .. "''" end
table.insert(ret, parent)
-- Track missing taxonomic name parent = mw.title.new(args[3])
if not (parent and parent.exists) then table.insert(categories, "Entries using missing taxonomic name (" .. args[2] .. ")") end
-- Vernacular name if args[4] then table.insert(ret, "&nbsp;– ") table.insert(ret, args[4]) else table.insert(categories, "Taxonomic names needing vernacular names") end
if not args["nodot"] then table.insert(ret, ".") end
return table.concat(ret) .. require("Module:utilities").format_categories(categories, lang_mul) end
return export

