return function (CSS_page)
	return mw.getCurrentFrame():extensionTag{
		name = "templatestyles", args = { src = CSS_page }
	}
end

.number-box {
	background: #ffffff;
	border: 1px #aaa solid;
	border-collapse: collapse;
	margin-top: .5em;
}
.number-box .current-slot {
	width: 98px;
	text-align: center;
	font-size:larger;
}
.number-box .adjacent-slot {
	width: 64px;
	background: #dddddd;
	text-align: center; 
	font-size: smaller;
}
.number-box .form-slot {
	text-align: center;
}
.number-box .footer-slot {
	text-align: center;
	background: #dddddd;
}
.number-box .adjacent-slot {
	width: 64px;
	background: #dddddd;
	text-align: center; 
	font-size: smaller;
}
.number-box .adjacent-panel {
	background: #ddd;
	text-align: center;
}
.number-box .table-cell {
	min-width: 6em;
}
.number-box .table-cell.current-number {
	font-size: larger;
}
.number-box .table-cell.adjacent-number {
	background: #ddd;
	font-size: smaller;
}
.number-box .table-cell.footer-cell {
	background: #ddd;
}

